Extensions.ExtractScript:
param([xml] $Document, [string] $Pass)
$utf8bom = [System.Text.UTF8Encoding]::new($true)
foreach ($file in $Document.GetElementsByTagName('File')) {
    if ($file.GetAttribute('pass') -ne $Pass) { continue }
    $path = [System.Environment]::ExpandEnvironmentVariables($file.GetAttribute('path'))
    New-Item -ItemType Directory -Path (Split-Path -Parent $path) -Force -ErrorAction SilentlyContinue | Out-Null
    [System.IO.File]::WriteAllText($path, $file.InnerText.Trim(), $utf8bom)
}

Extensions.File:
# Roda no WinPE, antes de qualquer coisa ser gravada. # Procura o disco alvo pelo serial ou pelo modelo. Só particiona se achar EXATAMENTE um; senão aborta # e o Setup para com erro, sem ter apagado nada. Pendrives nunca são candidatos.
$Serial = 'AA09B5211012T9' # Get-Disk | Select-Object FriendlyName, SerialNumber $Modelo = 'MP700 ELITE'
$log = 'X:\mywiniso\disco.log' function Log($m) { Write-Output $m; Add-Content -Path $log -Value $m }
$discos = @(Get-CimInstance -ClassName Win32_DiskDrive) Log "Discos vistos pelo WinPE:" foreach ($d in $discos) { Log (" [{0}] {1} | serial={2} | {3} GB | {4}" -f $d.Index, $d.Model, $d.SerialNumber, [math]::Round($d.Size / 1GB), $d.InterfaceType) }
$alvo = @($discos | Where-Object { $serialLimpo = ($_.SerialNumber -replace '[^A-Za-z0-9]', '') ($serialLimpo -like "*$Serial*" -or $_.Model -like "*$Modelo*") -and $_.InterfaceType -ne 'USB' -and $_.PNPDeviceID -notlike 'USBSTOR*' })
if ($alvo.Count -ne 1) { Log "ERRO: esperava 1 disco com serial '$Serial' ou modelo '$Modelo', achei $($alvo.Count). Nada foi apagado." Start-Process notepad.exe -ArgumentList $log -Wait exit 1 }
$n = $alvo[0].Index Log "Alvo: disco $n ($($alvo[0].Model)). Apagando e particionando (GPT: EFI 300 MB, MSR 16 MB, Windows, Recovery 1 GB)."
$script = @" select disk $n clean convert gpt create partition efi size=300 format quick fs=fat32 label="System" create partition msr size=16 create partition primary shrink minimum=1024 format quick fs=ntfs label="Windows" create partition primary format quick fs=ntfs label="Recovery" set id="de94bba4-06d1-4d40-a16a-bfd50179d6ac" gpt attributes=0x8000000000000001 list partition "@ $script | Set-Content -Path 'X:\mywiniso\diskpart.txt' -Encoding ASCII $saida = diskpart.exe /s 'X:\mywiniso\diskpart.txt' 2>&1 $saida | ForEach-Object { Log ([string]$_) } if ($LASTEXITCODE -ne 0) { Log "ERRO: diskpart saiu com código $LASTEXITCODE." Start-Process notepad.exe -ArgumentList $log -Wait exit $LASTEXITCODE } Log "Disco pronto." exit 0

# Roda no passo "specialize", como SYSTEM, antes do primeiro boot na área de trabalho. # Só coisas de sistema. Preferências de usuário (tema, barra, mouse) ficam no setup.ps1 do repositório.
$ErrorActionPreference = 'Continue' Start-Transcript -Path 'C:\Windows\Setup\Scripts\especializar.log' -Force | Out-Null
function Set-Reg([string] $Path, [string] $Name, $Value, [string] $Type = 'DWord') { if (-not (Test-Path -LiteralPath $Path)) { New-Item -Path $Path -Force | Out-Null } Set-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -Type $Type -Force }
# --- Bloatware: pacotes provisionados (nunca chegam a ser instalados para o usuário) --- # Ficam: Loja e App Installer (o winget depende deles), Calculadora, Fotos, Terminal, Xbox Identity Provider. # Bloco de Notas, Paint e Ferramenta de Captura saem: VS Code e Lightshot no lugar. $bloat = @( 'Clipchamp.Clipchamp', 'Microsoft.549981C3F5F10', 'Microsoft.BingNews', 'Microsoft.BingSearch', 'Microsoft.BingWeather', 'Microsoft.Copilot', 'Microsoft.Edge.GameAssist', 'Microsoft.GamingApp', 'Microsoft.GetHelp', 'Microsoft.Getstarted', 'Microsoft.Microsoft3DViewer', 'Microsoft.MicrosoftOfficeHub', 'Microsoft.MicrosoftSolitaireCollection', 'Microsoft.MicrosoftStickyNotes', 'Microsoft.MixedReality.Portal', 'Microsoft.MSPaint', 'Microsoft.Office.OneNote', 'Microsoft.OutlookForWindows', 'Microsoft.Paint', 'Microsoft.People', 'Microsoft.PowerAutomateDesktop', 'Microsoft.ScreenSketch', 'Microsoft.SkypeApp', 'Microsoft.Todos', 'Microsoft.Wallet', 'Microsoft.Windows.DevHome', 'Microsoft.WindowsAlarms', 'Microsoft.WindowsCamera', 'Microsoft.WindowsFeedbackHub', 'Microsoft.WindowsMaps', 'Microsoft.WindowsNotepad', 'Microsoft.WindowsSoundRecorder', 'Microsoft.Xbox.TCUI', 'Microsoft.XboxApp', 'Microsoft.XboxGameOverlay', 'Microsoft.XboxGamingOverlay', 'Microsoft.XboxSpeechToTextOverlay', 'Microsoft.YourPhone', 'Microsoft.ZuneMusic', 'Microsoft.ZuneVideo', 'MicrosoftCorporationII.MicrosoftFamily', 'MicrosoftCorporationII.QuickAssist', 'MicrosoftTeams', 'MSTeams', 'microsoft.windowscommunicationsapps' ) Get-AppxProvisionedPackage -Online | Where-Object { $bloat -contains $_.DisplayName } | ForEach-Object { Write-Output "removendo $($_.DisplayName)" Remove-AppxProvisionedPackage -Online -PackageName $_.PackageName | Out-Null }
# --- Capacidades (recursos sob demanda) --- $capacidades = @( 'App.StepsRecorder', 'App.Support.QuickAssist', 'Browser.InternetExplorer', 'Hello.Face.18967', 'Hello.Face.20134', 'Hello.Face.Migration.18967', 'Language.Handwriting', 'Language.Speech', 'Language.TextToSpeech', 'MathRecognizer', 'Media.WindowsMediaPlayer', 'Microsoft.Windows.MSPaint', 'Microsoft.Windows.PowerShell.ISE', 'Microsoft.Windows.SnippingTool', 'Microsoft.Windows.WordPad', 'OneCoreUAP.OneSync', 'OpenSSH.Client', 'Print.Fax.Scan' ) Get-WindowsCapability -Online | Where-Object { $_.State -notin 'NotPresent', 'Removed' -and $capacidades -contains ($_.Name -split '~')[0] } | ForEach-Object { Write-Output "removendo capacidade $($_.Name)" Remove-WindowsCapability -Online -Name $_.Name -ErrorAction Continue | Out-Null }
# --- Recursos opcionais: PowerShell 2.0, cliente de Área de Trabalho Remota (mstsc), Recall, Captura --- # MediaPlayback fica: jogos e apps usam para vídeo. foreach ($f in 'MicrosoftWindowsPowerShellV2Root', 'Microsoft-RemoteDesktopConnection', 'Recall', 'Microsoft-SnippingTool') { Disable-WindowsOptionalFeature -Online -FeatureName $f -Remove -NoRestart -ErrorAction SilentlyContinue | Out-Null }
# Outlook e Dev Home ficam agendados para instalar depois do OOBE; tirar o agendamento. Teams idem. foreach ($k in 'OutlookUpdate', 'DevHomeUpdate') { Remove-Item -LiteralPath "HKLM:\SOFTWARE\Microsoft\WindowsUpdate\Orchestrator\UScheduler_Oobe\$k" -Force -ErrorAction SilentlyContinue } Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Communications' 'ConfigureChatAutoInstall' 0
# Sem o Bloco de Notas, "Novo > Documento de Texto" continua existindo reg.exe add "HKCR\txtfilelegacy" /ve /t REG_SZ /d "Text Document" /f | Out-Null reg.exe add "HKCR\txtfilelegacy" /v FriendlyTypeName /t REG_EXPAND_SZ /d "@C:\Windows\system32\notepad.exe,-469" /f | Out-Null reg.exe add "HKCR\.txt\ShellNew" /v ItemName /t REG_EXPAND_SZ /d "@C:\Windows\system32\notepad.exe,-470" /f | Out-Null reg.exe add "HKCR\.txt\ShellNew" /v NullFile /t REG_SZ /f | Out-Null
# --- OneDrive: desinstala e tira do autostart do perfil padrão --- foreach ($exe in "$env:SystemRoot\System32\OneDriveSetup.exe", "$env:SystemRoot\SysWOW64\OneDriveSetup.exe") { if (Test-Path -LiteralPath $exe) { Start-Process -FilePath $exe -ArgumentList '/uninstall' -Wait } } Remove-Item -LiteralPath 'C:\Users\Default\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\OneDrive.lnk' -Force -ErrorAction SilentlyContinue reg.exe load HKU\DefaultUser C:\Users\Default\NTUSER.DAT | Out-Null reg.exe delete "HKU\DefaultUser\Software\Microsoft\Windows\CurrentVersion\Run" /v OneDriveSetup /f 2>$null reg.exe unload HKU\DefaultUser | Out-Null
# --- Políticas: telemetria, sugestões, Copilot, widgets, anúncios, Edge --- Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\OOBE' 'BypassNRO' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\DataCollection' 'AllowTelemetry' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableWindowsConsumerFeatures' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\CloudContent' 'DisableCloudOptimizedContent' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot' 'TurnOffWindowsCopilot' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Dsh' 'AllowNewsAndInterests' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\AdvertisingInfo' 'DisabledByGroupPolicy' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge' 'HideFirstRunExperience' 1 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' 'BackgroundModeEnabled' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Edge\Recommended' 'StartupBoostEnabled' 0 Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU' 'NoAutoRebootWithLoggedOnUsers' 1
# Edge desinstalável (política regional que a Microsoft aplica na Europa) try { $arq = 'C:\Windows\System32\IntegratedServicesRegionPolicySet.json' $o = Get-Content -LiteralPath $arq -Encoding UTF8 | ConvertFrom-Json $o.policies | Where-Object { $_.guid -eq '{1bca278a-5d11-4acf-ad2f-f9ab6d7f93a6}' } | ForEach-Object { $_.defaultState = 'enabled' } $o | ConvertTo-Json -Depth 9 | Out-File -LiteralPath $arq -Encoding UTF8 } catch { Write-Output "Edge desinstalável: $_" }
# Menu Iniciar sem nada fixado Set-Reg 'HKLM:\SOFTWARE\Microsoft\PolicyManager\current\device\Start' 'ConfigureStartPins' '{"pinnedList":[]}' 'String'
# --- Segurança que atrapalha: UAC sem perguntar (mantendo o LUA, senão apps da Loja não abrem), # Smart App Control e SmartScreen desligados, ícone da Segurança do Windows escondido --- $sys = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System' Set-Reg $sys 'ConsentPromptBehaviorAdmin' 0 Set-Reg $sys 'PromptOnSecureDesktop' 0 Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\CI\Policy' 'VerifiedAndReputablePolicyState' 0 Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer' 'SmartScreenEnabled' 'Off' 'String' $wtds = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WTDS\Components' foreach ($n in 'ServiceEnabled', 'NotifyMalicious', 'NotifyPasswordReuse', 'NotifyUnsafeApp') { Set-Reg $wtds $n 0 } Set-Reg 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Systray' 'HideSystray' 1
# --- Sistema --- Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Power' 'HiberbootEnabled' 0 # inicialização rápida desligada Set-Reg 'HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem' 'LongPathsEnabled' 1 Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Authentication\LogonUI\BootAnimation' 'DisableStartupSound' 1 Set-Reg 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\EditionOverrides' 'UserSetting_DisableStartupSound' 1 net.exe accounts /maxpwage:unlimited | Out-Null net.exe accounts /lockoutthreshold:0 | Out-Null
# Plano de energia "Alto desempenho" já no primeiro boot; o setup.ps1 troca para Desempenho Máximo $alto = '8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c' powercfg.exe /setactive $alto 2>$null if ($LASTEXITCODE -ne 0) { $saida = powercfg.exe /duplicatescheme $alto if ($saida -match '([0-9a-f-]{36})') { powercfg.exe /setactive $Matches[1] } }
Stop-Transcript | Out-Null exit 0
